const Layout=({children})=><RoleLayout role="Manager" base="/manager" menu={managerMenu}><div className="manager-live">{children}</div></RoleLayout>;
const Header=({title,subtitle,actions})=><section className="role-hero manager-live-head"><div><h1>{title}</h1><p>{subtitle}</p></div>{actions&&<div className="manager-live-actions">{actions}</div>}</section>;
const Badge=({children})=><span className={`role-badge ${["Approved","Completed","Active","Present"].includes(children)?"success":["Rejected","Cancelled","Blocked","Absent"].includes(children)?"danger":["Pending","Submitted","Late","Ready for Review","At Risk"].includes(children)?"warning":"info"}`}>{children||"-"}</span>;
const State=({loading,error,retry,children,empty})=>loading?<LoadingState message="Loading live Manager data..."/>:error?<><ErrorState message={error}/><button className="role-action" onClick={retry}>Retry</button></>:empty?<EmptyState message={empty}/>:children;
const err=e=>{const d=e?.response?.data;if(d?.message)return d.message;if(d?.errors)return Object.values(d.errors).flat().join(" ");return e?.message||"The operation could not be completed."};
const day=v=>{if(!v)return "-";const raw=String(v);if(/^\d{4}-\d{2}-\d{2}/.test(raw))return raw.slice(0,10);const d=v instanceof Date?v:new Date(v);return Number.isNaN(d.getTime())?"-":d.toISOString().slice(0,10)};
const when=v=>v?new Date(v).toLocaleString():"-";
const monthCells=cursor=>{const first=new Date(cursor.getFullYear(),cursor.getMonth(),1),offset=(first.getDay()+6)%7,start=new Date(cursor.getFullYear(),cursor.getMonth(),1-offset);return Array.from({length:42},(_,i)=>new Date(start.getFullYear(),start.getMonth(),start.getDate()+i))};
const useLive=(loader,deps=[])=>{const [state,setState]=useState({loading:true,error:"",data:null});const reload=useCallback(async()=>{setState(s=>({...s,loading:true,error:""}));try{setState({loading:false,error:"",data:await loader()})}catch(e){setState({loading:false,error:err(e),data:null})}},deps);useEffect(()=>{reload()},[reload]);return{...state,reload}};
const Panel=({title,children,className=""})=><section className={`role-card manager-live-panel ${className}`}><h2>{title}</h2>{children}</section>;
const Table=({headers,children})=><div className="role-table-wrap"><table className="role-table"><thead><tr>{headers.map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{children}</tbody></table></div>;
const Modal=({title,onClose,children})=><div className="employee-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="employee-detail-modal role-card" role="dialog" aria-modal="true"><div className="employee-section-header"><h2>{title}</h2><button className="role-soft" onClick={onClose}>Close</button></div>{children}</section></div>;

